import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"VLLM K/V Caching With Ceph - Kyle Bader, IBM & Tushar Gohad, Intel","description":"","frontmatter":{"title":"VLLM K/V Caching With Ceph - Kyle Bader, IBM & Tushar Gohad, Intel","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","AI存储优化","LLM Inference","KV Cache","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/VLLM_K_V_Caching_With_Ceph_-_Kyle_Bader_IBM_Tushar_Gohad_Intel.md","filePath":"posts/2025/VLLM_K_V_Caching_With_Ceph_-_Kyle_Bader_IBM_Tushar_Gohad_Intel.md","lastUpdated":1780459816000}'),h={name:"posts/2025/VLLM_K_V_Caching_With_Ceph_-_Kyle_Bader_IBM_Tushar_Gohad_Intel.md"};function n(l,e,i,s,_,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h3 id="ceph-与-ai-存储优化技术研讨会会议纪要" tabindex="-1">Ceph 与 AI 存储优化技术研讨会会议纪要 <a class="header-anchor" href="#ceph-与-ai-存储优化技术研讨会会议纪要" aria-label="Permalink to &quot;Ceph 与 AI 存储优化技术研讨会会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1"><strong>会议主题</strong> <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;**会议主题**&quot;">​</a></h4><p>本次研讨会探讨了 Ceph 分布式存储在 AI 大模型推理（LLM Inference）中的应用，特别是通过 KV Cache 缓存优化解决 GPU 内存瓶颈问题，并提升推理效率。</p><h4 id="关键讨论内容" tabindex="-1"><strong>关键讨论内容</strong> <a class="header-anchor" href="#关键讨论内容" aria-label="Permalink to &quot;**关键讨论内容**&quot;">​</a></h4><h5 id="_1-ai-推理中的存储挑战" tabindex="-1"><strong>1. AI 推理中的存储挑战</strong> <a class="header-anchor" href="#_1-ai-推理中的存储挑战" aria-label="Permalink to &quot;**1. AI 推理中的存储挑战**&quot;">​</a></h5><ul><li><strong>KV Cache 的线性增长问题</strong>：随着上下文长度（Context Length）的增加，KV Cache 需求线性增长，导致 GPU 内存不足，影响并发请求数和 GPU 利用率。</li><li><strong>计算与存储的权衡</strong>：Prefill 阶段的计算复杂度为 O(n²)，而存储 KV Cache 的复杂度为 O(1)，通过将 KV Cache 卸载到共享存储（如 Ceph）可以优化计算资源。</li></ul><h5 id="_2-ceph-作为-kv-cache-存储层的优势" tabindex="-1"><strong>2. Ceph 作为 KV Cache 存储层的优势</strong> <a class="header-anchor" href="#_2-ceph-作为-kv-cache-存储层的优势" aria-label="Permalink to &quot;**2. Ceph 作为 KV Cache 存储层的优势**&quot;">​</a></h5><ul><li><strong>实验架构</strong>：使用 VLLM（Berkeley 推理框架）+ LM Cache（KV Cache 管理器）+ Ceph RGW（S3 接口）。</li><li><strong>性能</strong>：单客户端可驱动 60GB/s 读取带宽，满足高吞吐需求。</li><li><strong>内容寻址存储</strong>：KV Cache 块通过哈希映射到 S3 对象，无需元数据库，支持无状态扩展和弹性存储。</li></ul><h5 id="_3-性能收益与案例分析" tabindex="-1"><strong>3. 性能收益与案例分析</strong> <a class="header-anchor" href="#_3-性能收益与案例分析" aria-label="Permalink to &quot;**3. 性能收益与案例分析**&quot;">​</a></h5><ul><li><strong>时间优化</strong>：在 100K Token 上下文场景下，通过 Ceph 读取 KV Cache 可实现 5-10 倍的 Time-to-First-Token（TTFT）加速。</li><li><strong>成本效益</strong>：存储 KV Cache 的成本远低于 GPU 计算开销。</li></ul><h5 id="_4-未来方向" tabindex="-1"><strong>4. 未来方向</strong> <a class="header-anchor" href="#_4-未来方向" aria-label="Permalink to &quot;**4. 未来方向**&quot;">​</a></h5><ul><li><strong>分布式推理优化</strong>：结合 LLMD（Red Hat/Google 分布式推理框架）实现 Prefill/Decode 解耦，支持异构加速器。</li><li><strong>技术扩展</strong>：探索 NFS over RDMA 或 GPU Direct Storage 进一步降低延迟，研究 KV Cache 分区加密提升数据安全性。</li></ul><h5 id="行动计划" tabindex="-1"><strong>行动计划</strong> <a class="header-anchor" href="#行动计划" aria-label="Permalink to &quot;**行动计划**&quot;">​</a></h5><ol><li><strong>Ceph 与 VLLM/LM Cache 集成</strong>：将现有实验成果文档化，推动成为 VLLM 官方支持的存储后端。</li><li><strong>性能基准测试</strong>：使用真实 AI 负载 Trace 验证缓存命中率与扩展性。</li><li><strong>生态合作</strong>：与 NeoCloud 厂商合作，提供 KV Cache-as-a-Service 解决方案。</li></ol><h4 id="会议结论" tabindex="-1"><strong>会议结论</strong> <a class="header-anchor" href="#会议结论" aria-label="Permalink to &quot;**会议结论**&quot;">​</a></h4><p>Ceph 的高吞吐和弹性扩展能力使其成为 AI 推理 KV Cache 卸载的理想存储层，未来需进一步优化生态集成与多租户支持。</p>',16)])])}const C=a(h,[["render",n]]);export{g as __pageData,C as default};
